-- Adds the three Woman Cares dashboards (client, professional, Super Admin) with their numbered
-- markers to the project. Does nothing when the project is missing or already has dashboard screens.
-- Mirrors seedDashboardTours in prisma/seed.ts.
DO $wc$
DECLARE
  pid TEXT;
  mid TEXT;
  iid TEXT;
BEGIN
  SELECT "id" INTO pid FROM "Project" WHERE "slug" = 'woman-cares';
  IF pid IS NULL OR EXISTS (SELECT 1 FROM "ProjectImage" WHERE "projectId" = pid AND "section" = 'DASHBOARD') THEN
    RETURN;
  END IF;


  INSERT INTO "MediaAsset" ("id", "driver", "storageKey", "url", "kind", "mimeType", "width", "height", "bytes", "alt", "label")
  VALUES (gen_random_uuid()::TEXT, 'LOCAL', 'public:/projects/woman-cares/dashboard-client.webp', '/projects/woman-cares/dashboard-client.webp', 'IMAGE', 'image/webp', 1600, 1000, 0, '{"en":"Woman Cares client dashboard with demo appointments","fr":"Espace cliente Woman Cares avec des rendez-vous de démonstration","ar":"لوحة العميلة في Woman Cares بمواعيد تجريبية"}'::JSONB, 'woman-cares dashboard: Client dashboard')
  ON CONFLICT ("storageKey") DO UPDATE SET "storageKey" = EXCLUDED."storageKey"
  RETURNING "id" INTO mid;
  iid := gen_random_uuid()::TEXT;
  INSERT INTO "ProjectImage" ("id", "projectId", "mediaId", "kind", "section", "title", "sortOrder")
  VALUES (iid, pid, mid, 'DEMO', 'DASHBOARD', '{"en":"Client dashboard","fr":"Espace cliente","ar":"لوحة العميلة"}'::JSONB, 0);
  INSERT INTO "ProjectHotspot" ("id", "imageId", "x", "y", "icon", "label", "body", "sortOrder")
  VALUES (gen_random_uuid()::TEXT, iid, 15.2, 15.7, 'calendar', '{"en":"My appointments","fr":"Mes rendez-vous","ar":"مواعيدي"}'::JSONB, '{"en":"Every appointment with filters. Open one to cancel it, answer a new time proposed by the professional, or leave a review once it is done.","fr":"Tous les rendez-vous avec filtres. On en ouvre un pour l''annuler, répondre à un nouvel horaire proposé par la professionnelle ou laisser un avis une fois terminé.","ar":"كل المواعيد مع الفلاتر. افتحي موعدًا لإلغائه أو للرد على وقت جديد تقترحه المحترفة أو لكتابة تقييم بعد انتهائه."}'::JSONB, 0);
  INSERT INTO "ProjectHotspot" ("id", "imageId", "x", "y", "icon", "label", "body", "sortOrder")
  VALUES (gen_random_uuid()::TEXT, iid, 15.2, 24, 'bell', '{"en":"Notifications","fr":"Notifications","ar":"الإشعارات"}'::JSONB, '{"en":"In-app notices when a professional accepts, declines or proposes another time. The same events also arrive by email.","fr":"Avis dans l''application quand une professionnelle accepte, refuse ou propose un autre horaire. Les mêmes événements arrivent aussi par e-mail.","ar":"إشعارات داخل التطبيق عندما تقبل المحترفة أو ترفض أو تقترح وقتًا آخر، وتصل الأحداث نفسها بالبريد أيضًا."}'::JSONB, 1);
  INSERT INTO "ProjectHotspot" ("id", "imageId", "x", "y", "icon", "label", "body", "sortOrder")
  VALUES (gen_random_uuid()::TEXT, iid, 15.2, 28.2, 'user-cog', '{"en":"Profile and settings","fr":"Profil et réglages","ar":"الملف والإعدادات"}'::JSONB, '{"en":"Name, phone, language and which notifications to receive.","fr":"Nom, téléphone, langue et notifications à recevoir.","ar":"الاسم والهاتف واللغة والإشعارات التي ترغبين في تلقيها."}'::JSONB, 2);
  INSERT INTO "ProjectHotspot" ("id", "imageId", "x", "y", "icon", "label", "body", "sortOrder")
  VALUES (gen_random_uuid()::TEXT, iid, 56.5, 37.5, 'clock', '{"en":"Next appointments","fr":"Prochains rendez-vous","ar":"المواعيد القادمة"}'::JSONB, '{"en":"Confirmed appointments with the professional, the service and the time.","fr":"Les rendez-vous confirmés, avec la professionnelle, la prestation et l''heure.","ar":"المواعيد المؤكَّدة مع المحترفة والخدمة والوقت."}'::JSONB, 3);
