  INSERT INTO "ProjectHotspot" ("id", "imageId", "x", "y", "icon", "label", "body", "sortOrder")
  VALUES (gen_random_uuid()::TEXT, iid, 15.2, 15.7, 'clipboard-list', '{"en":"Bookings","fr":"Rendez-vous","ar":"الحجوزات"}'::JSONB, '{"en":"The bookings table: to handle, today, upcoming, past, cancelled. Accept, decline, propose a new time, complete or mark a no-show. The badge counts requests waiting.","fr":"Le tableau des réservations : à traiter, aujourd''hui, à venir, passées, annulées. Accepter, refuser, proposer un autre horaire, terminer ou noter une absence. Le badge compte les demandes en attente.","ar":"جدول الحجوزات: للمعالجة واليوم والقادمة والسابقة والملغاة. قبول أو رفض أو اقتراح وقت جديد أو إنهاء أو تسجيل غياب. تعرض الشارة عدد الطلبات المنتظرة."}'::JSONB, 0);
  INSERT INTO "ProjectHotspot" ("id", "imageId", "x", "y", "icon", "label", "body", "sortOrder")
  VALUES (gen_random_uuid()::TEXT, iid, 15.2, 19.9, 'calendar', '{"en":"Calendar","fr":"Calendrier","ar":"التقويم"}'::JSONB, '{"en":"A week grid with opening hours, closures and overlapping appointments side by side. She can add an appointment by hand, for a walk-in or a phone call.","fr":"Une grille de la semaine avec horaires, fermetures et rendez-vous qui se chevauchent côte à côte. Elle peut ajouter un rendez-vous à la main, pour une cliente de passage ou un appel.","ar":"شبكة أسبوعية فيها أوقات العمل وأيام الإغلاق والمواعيد المتداخلة جنبًا إلى جنب. يمكنها إضافة موعد يدويًا لعميلة حضرت أو اتصلت."}'::JSONB, 1);
  INSERT INTO "ProjectHotspot" ("id", "imageId", "x", "y", "icon", "label", "body", "sortOrder")
