  VALUES (gen_random_uuid()::TEXT, iid, 15.2, 15.7, 'list-checks', '{"en":"Professionals","fr":"Professionnelles","ar":"المحترفات"}'::JSONB, '{"en":"The review queue. Publish a profile, ask for changes, suspend, approve an account, grant the verified badge, check Botox credentials. Every decision is saved in the log and emailed.","fr":"La file de validation. Publier un profil, demander des changements, suspendre, approuver un compte, accorder le badge vérifié, contrôler les diplômes Botox. Chaque décision est journalisée et envoyée par e-mail.","ar":"قائمة المراجعة. نشر ملف أو طلب تعديلات أو تعليق أو الموافقة على حساب أو منح شارة التحقق أو فحص شهادات البوتوكس. يُسجَّل كل قرار ويُرسل بالبريد."}'::JSONB, 0);
